schema @link(url: "https://specs.apollo.dev/federation/v2.5", import: ["@key"]) {
  query: Query
  mutation: Mutation
}

input AddOrganizationInput {
  name: String!
  alias: String!
  enabled: Boolean!
  description: String = null
}

input AddOrganizationMemberInput {
  organizationId: ID!
  userId: ID!
}

type AddOrganizationMemberPayload {
  success: Boolean!
}

input AddUserInput {
  username: String!
  email: String!
  enabled: Boolean!
  credentials: [Credential!]!
}

input Credential {
  type: String!
  value: String!
}

type Domain {
  name: String!
  verified: Boolean!
}

type Group {
  id: ID!
  name: String!
  description: String
  path: String
  parentId: String
  subGroupCount: Int
  members: [Member!]
}

type Member {
  id: ID!
  username: String!
  firstName: String
  lastName: String
  email: String!
  emailVerified: Boolean!
  enabled: Boolean!
}

type Mutation {
  addUser(input: AddUserInput!): User!
  createOrganization(input: AddOrganizationInput!): OrganizationCreateConfirmation!
  updateOrganization(id: ID!, input: UpdateOrganizationInput!): Organization!
  activateOrganization(id: ID!): Organization!
  deactivateOrganization(id: ID!): Organization!
  addOrganizationMember(input: AddOrganizationMemberInput!): AddOrganizationMemberPayload!
  removeOrganizationMember(input: RemoveOrganizationMemberInput!): RemoveOrganizationMemberPayload!
}

type Organization @key(fields: "id") {
  id: ID!
  name: String!
  alias: String!
  enabled: Boolean!
  description: String
  domains: [Domain!]!
  members: [Member!]
  groups: [Group!]
}

type OrganizationCreateConfirmation {
  name: String!
  success: Status!
}

type Query {
  _entities(representations: [_Any!]!): [_Entity]!
  _service: _Service!
  users: [User!]!
  user(id: ID!): User!
  organizations: [Organization!]!
  organization(id: ID!): Organization!
}

input RemoveOrganizationMemberInput {
  organizationId: ID!
  userId: ID!
}

type RemoveOrganizationMemberPayload {
  success: Boolean!
}

enum Status {
  SUCCESS
  FAILED
}

input UpdateOrganizationInput {
  name: String = null
  alias: String = null
  enabled: Boolean = null
  description: String = null
}

type User @key(fields: "id") {
  id: ID!
  username: String!
  firstName: String
  lastName: String
  email: String!
  emailVerified: Boolean!
  enabled: Boolean!
}

scalar _Any

union _Entity = Organization | User

type _Service {
  sdl: String!
}

